// --- prototypes generated by arduino_sim.py (the Arduino IDE/Tinkercad do the same) ---
void setup();
void loop();
// Lab internal LED, Task 4 (bonus): blink at 2 Hz (toggle every 250 ms) AND print the number of blinks every 5 s
const unsigned long TOGGLE_PERIOD = 250;   // 2 Hz = period 500 ms = toggle every 250 ms
const unsigned long REPORT_PERIOD = 5000;
unsigned long prevToggle = 0, prevReport = 0;
bool ledOn = false;
unsigned long blinks = 0;                  // one blink = one ON phase

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  unsigned long now = millis();
  if (now - prevToggle >= TOGGLE_PERIOD) {
    prevToggle = now;
    ledOn = !ledOn;
    digitalWrite(LED_BUILTIN, ledOn);
    if (ledOn) blinks++;
  }
  if (now - prevReport >= REPORT_PERIOD) {
    prevReport = now;
    Serial.print("Blinks so far: ");
    Serial.println(blinks);
  }
}
